# -*- coding: utf-8 -*-
"""
Datos de estado de cuenta desde la base de datos (fuente unica para PDF, API JSON y consumidores).

Ver backend/docs/ESTADO_CUENTA_FUENTE_UNICA.md.
"""
from __future__ import annotations

import copy
import logging
import re
from typing import Any, Dict, List, Optional

from sqlalchemy import and_, desc, func, select
from sqlalchemy.orm import Session

from app.models.cliente import Cliente
from app.models.cuota import Cuota
from app.models.cuota_pago import CuotaPago
from app.models.pago import Pago
from app.models.pago_reportado import PagoReportado
from app.models.prestamo import Prestamo
from app.services.cobros.pago_reportado_documento import claves_documento_pago_para_reportado
from app.services.cuota_estado import etiqueta_estado_cuota, estado_cuota_para_mostrar, hoy_negocio
from app.services.pagos.comprobante_link_desde_gmail import (
    comprobante_url_para_enlace_publico,
    enriquecer_items_link_comprobante_desde_gmail,
)
from app.services.pagos_cuotas_sincronizacion import sincronizar_pagos_pendientes_a_prestamos
from app.utils.cliente_emails import emails_destino_desde_objeto
from app.utils.cedula_almacenamiento import expr_cedula_normalizada_para_comparar

logger = logging.getLogger(__name__)

# Prestamos cuyo PDF/API incluyen la tabla completa de amortizacion (todas las cuotas).
ESTADOS_PRESTAMO_TABLA_AMORTIZACION = frozenset({"APROBADO", "LIQUIDADO"})
# Portal / PDF estado de cuenta: solo cartera operativa o cerrada por pago; nunca desistimiento.
ESTADOS_PRESTAMO_ESTADO_CUENTA = frozenset({"APROBADO", "LIQUIDADO"})
ESTADOS_PRESTAMO_EXCLUIDOS_ESTADO_CUENTA = frozenset(
    {"DESISTIMIENTO", "DESESTIMADO", "DESISTIDO"}
)
ESTADO_PRESTAMO_LIQUIDADO = "LIQUIDADO"
ESTADO_PRESTAMO_APROBADO = "APROBADO"

MSG_PORTAL_ESTADO_CUENTA_NO_ELEGIBLE = "Comuníquese con un asesor."
MSG_PORTAL_ESTADO_CUENTA_DESISTIMIENTO = (
    "Su crédito está en estado de desistimiento (desestimado). "
    "No puede consultar el estado de cuenta en línea. Comuníquese con un asesor."
)


def _norm_estado_prestamo(estado: Optional[str]) -> str:
    return (estado or "").strip().upper()


def estado_prestamo_es_liquidado(estado: Optional[str]) -> bool:
    return _norm_estado_prestamo(estado) == ESTADO_PRESTAMO_LIQUIDADO


def estado_prestamo_es_desistimiento(estado: Optional[str]) -> bool:
    return _norm_estado_prestamo(estado) in ESTADOS_PRESTAMO_EXCLUIDOS_ESTADO_CUENTA


def estado_prestamo_permite_estado_cuenta(estado: Optional[str]) -> bool:
    """APROBADO o LIQUIDADO. Nunca DESISTIMIENTO (ni variantes)."""
    est = _norm_estado_prestamo(estado)
    if not est or est in ESTADOS_PRESTAMO_EXCLUIDOS_ESTADO_CUENTA:
        return False
    return est in ESTADOS_PRESTAMO_ESTADO_CUENTA


def cedula_tiene_algun_prestamo_desistimiento(db: Session, cedula_lookup: str) -> bool:
    """True si la cédula tiene al menos un préstamo DESISTIMIENTO (variantes)."""
    lu = (cedula_lookup or "").strip()
    if not lu:
        return False
    row = db.execute(
        select(Prestamo.id)
        .join(Cliente, Prestamo.cliente_id == Cliente.id)
        .where(
            expr_cedula_normalizada_para_comparar(Cliente.cedula) == lu,
            func.upper(func.trim(func.coalesce(Prestamo.estado, ""))).in_(
                tuple(ESTADOS_PRESTAMO_EXCLUIDOS_ESTADO_CUENTA)
            ),
        )
        .limit(1)
    ).first()
    return row is not None


def mensaje_no_elegible_estado_cuenta_portal(
    db: Session, cedula_lookup: str
) -> str:
    """
    Texto cuando la cédula no puede usar el portal de estado de cuenta.
    Distingue desistimiento puro de otros casos.
    """
    if cedula_tiene_algun_prestamo_desistimiento(db, cedula_lookup):
        if not cedula_tiene_prestamo_elegible_estado_cuenta(db, cedula_lookup):
            return MSG_PORTAL_ESTADO_CUENTA_DESISTIMIENTO
    return MSG_PORTAL_ESTADO_CUENTA_NO_ELEGIBLE


def cedula_tiene_prestamo_elegible_estado_cuenta(db: Session, cedula_lookup: str) -> bool:
    """True si la cédula tiene al menos un préstamo APROBADO o LIQUIDADO."""
    lu = (cedula_lookup or "").strip()
    if not lu:
        return False
    row = db.execute(
        select(Prestamo.id)
        .join(Cliente, Prestamo.cliente_id == Cliente.id)
        .where(
            expr_cedula_normalizada_para_comparar(Cliente.cedula) == lu,
            func.upper(func.trim(func.coalesce(Prestamo.estado, ""))).in_(
                tuple(ESTADOS_PRESTAMO_ESTADO_CUENTA)
            ),
        )
        .limit(1)
    ).first()
    return row is not None


def cedula_tiene_prestamo_liquidado(db: Session, cedula_lookup: str) -> bool:
    """Compat: True si hay al menos un LIQUIDADO (preferir elegible_estado_cuenta)."""
    lu = (cedula_lookup or "").strip()
    if not lu:
        return False
    row = db.execute(
        select(Prestamo.id)
        .join(Cliente, Prestamo.cliente_id == Cliente.id)
        .where(
            expr_cedula_normalizada_para_comparar(Cliente.cedula) == lu,
            func.upper(func.trim(func.coalesce(Prestamo.estado, "")))
            == ESTADO_PRESTAMO_LIQUIDADO,
        )
        .limit(1)
    ).first()
    return row is not None


def prestamo_muestra_tabla_amortizacion(estado_prestamo: str) -> bool:
    return (estado_prestamo or "").strip().upper() in ESTADOS_PRESTAMO_TABLA_AMORTIZACION


def obtener_recibos_cliente_estado_cuenta(db: Session, cedula_lookup: str) -> List[dict]:
    """Pagos reportados del cliente (cédula comparable a ``texto_cedula_comparable_bd``) con recibo PDF."""
    cedula_concat = func.concat(
        func.coalesce(PagoReportado.tipo_cedula, ""),
        func.coalesce(PagoReportado.numero_cedula, ""),
    )
    rows = db.execute(
        select(PagoReportado)
        .where(
            and_(
                expr_cedula_normalizada_para_comparar(cedula_concat) == cedula_lookup,
                PagoReportado.recibo_pdf.isnot(None),
            )
        )
        .order_by(PagoReportado.fecha_pago.desc())
    ).scalars().all()
    out = []
    claves_por_fila: list[list[str]] = []
    for row in rows:
        pr = row[0] if hasattr(row, "__getitem__") else row
        fp = getattr(pr, "fecha_pago", None)
        fecha_str = fp.isoformat() if fp else ""
        claves_por_fila.append(claves_documento_pago_para_reportado(pr))
        out.append(
            {
                "id": pr.id,
                "referencia_interna": getattr(pr, "referencia_interna", "") or "",
                "fecha_pago": fecha_str,
                "monto": float(getattr(pr, "monto", 0) or 0),
                "moneda": getattr(pr, "moneda", "BS") or "BS",
                "aplicado_a_cuotas": False,
            }
        )
    if out:
        flat: list[str] = []
        for ks in claves_por_fila:
            flat.extend(ks)
        num_docs = list(dict.fromkeys(flat))
        pagos_aplicados: set[str] = set()
        if num_docs:
            pagos_aplicados = set(
                row[0]
                for row in db.execute(
                    select(Pago.numero_documento).where(
                        Pago.numero_documento.in_(num_docs),
                        Pago.estado == "PAGADO",
                    )
                ).all()
            )
        for r, ks in zip(out, claves_por_fila):
            r["aplicado_a_cuotas"] = bool(ks) and any(k in pagos_aplicados for k in ks)
    return out

def _fmt_fecha_hora_pago_estado_cuenta(dt) -> str:
    if dt is None:
        return "-"
    try:
        if hasattr(dt, "strftime"):
            return dt.strftime("%d/%m/%Y %H:%M")
    except Exception:
        pass
    return str(dt)


def obtener_pago_para_recibo_cuota(db: Session, cuota: Cuota) -> Optional[Pago]:
    """
    Pago con el que enriquecer el recibo de cuota (banco, operacion, fechas).
    Reune cuota.pago_id y todos los pagos enlazados en cuota_pagos (deduplicados).
    Prefiere un Pago con institucion_bancaria no vacia para alinear con la tabla de pagos del estado de cuenta.
    """
    seen: set[int] = set()
    ordered: List[Pago] = []

    pid = getattr(cuota, "pago_id", None)
    if pid:
        p = db.get(Pago, pid)
        if p is not None and p.id not in seen:
            seen.add(p.id)
            ordered.append(p)

    for p in db.execute(
        select(Pago)
        .join(CuotaPago, CuotaPago.pago_id == Pago.id)
        .where(CuotaPago.cuota_id == cuota.id)
        .order_by(CuotaPago.id.desc())
    ).scalars().all():
        if p.id not in seen:
            seen.add(p.id)
            ordered.append(p)

    for cand in ordered:
        if (getattr(cand, "institucion_bancaria", None) or "").strip():
            return cand
    return ordered[0] if ordered else None


def texto_institucion_recibo_cuota(db: Session, pago: Optional[Pago]) -> str:
    """
    Texto de banco para el PDF: pagos.institucion_bancaria; si vacio, pagos_reportados por
    COB-{referencia_interna} en documento/referencia, o por numero_operacion igual al del pago
    (cargas donde la operacion coincide con el reporte pero la columna banco en pagos quedo null).
    """
    if pago is None:
        return "N/A"
    ib = (getattr(pago, "institucion_bancaria", None) or "").strip()
    if ib:
        return ib[:100]
    seen_ref: set[str] = set()
    for raw in (getattr(pago, "numero_documento", None), getattr(pago, "referencia_pago", None)):
        doc = (raw or "").strip()
        up = doc.upper()
        if not up.startswith("COB-"):
            continue
        ref = doc[4:].strip()
        if not ref or ref in seen_ref:
            continue
        seen_ref.add(ref)
        fin = db.execute(
            select(PagoReportado.institucion_financiera)
            .where(PagoReportado.referencia_interna == ref)
            .order_by(desc(PagoReportado.id))
            .limit(1)
        ).scalar_one_or_none()
        s = (fin or "").strip() if fin is not None else ""
        if s:
            return s[:100]
    seen_op: set[str] = set()
    for raw in (getattr(pago, "referencia_pago", None), getattr(pago, "numero_documento", None)):
        op = (raw or "").strip()
        if not op or op.upper().startswith("COB-") or op in seen_op:
            continue
        seen_op.add(op)
        fin = db.execute(
            select(PagoReportado.institucion_financiera)
            .where(PagoReportado.numero_operacion == op)
            .order_by(desc(PagoReportado.id))
            .limit(1)
        ).scalar_one_or_none()
        s = (fin or "").strip() if fin is not None else ""
        if s:
            return s[:100]
    return "N/A"


def _prestamo_cuota_recibo_desde_pago(db: Session, pago_id: int):
    row = db.execute(
        select(Cuota.prestamo_id, Cuota.id)
        .where(Cuota.pago_id == pago_id)
        .order_by(Cuota.numero_cuota.asc())
        .limit(1)
    ).first()
    if row:
        return int(row[0]), int(row[1])
    row = db.execute(
        select(Cuota.prestamo_id, Cuota.id)
        .join(CuotaPago, CuotaPago.cuota_id == Cuota.id)
        .where(CuotaPago.pago_id == pago_id)
        .order_by(Cuota.numero_cuota.asc())
        .limit(1)
    ).first()
    if row:
        return int(row[0]), int(row[1])



def desglose_aplicacion_cuotas_por_pago(db: Session, pago_id: int) -> List[dict]:
    """CuotaPago por pago: monto aplicado a cada cuota vs monto de cuota (pago total puede ser mayor)."""
    rows = db.execute(
        select(Cuota, CuotaPago.monto_aplicado)
        .join(CuotaPago, CuotaPago.cuota_id == Cuota.id)
        .where(CuotaPago.pago_id == pago_id)
        .order_by(Cuota.numero_cuota.asc())
    ).all()
    out: List[dict] = []
    for row in rows:
        c = row[0]
        apl_raw = row[1]
        m_cuota = float(getattr(c, "monto", 0) or 0)
        apl = float(apl_raw or 0)
        pct_n = (apl / m_cuota * 100.0) if m_cuota > 0.0001 else 0.0
        if abs(pct_n - round(pct_n)) < 0.051:
            pct_str = f"{int(round(pct_n))}%"
        else:
            pct_str = f"{pct_n:.1f}%".replace(".", ",")
        out.append(
            {
                "numero_cuota": int(getattr(c, "numero_cuota", 0) or 0),
                "monto_cuota": m_cuota,
                "monto_aplicado": apl,
                "porcentaje_cuota": pct_str,
            }
        )
    return out



def _link_comprobante_es_url_http(val: Any) -> bool:
    s = (str(val or "")).strip()
    return bool(s and s.lower().startswith(("http://", "https://")))


# Referencia interna del reporte web (RPC-YYYYMMDD-NNNNN), con o sin prefijo COB- en cartera.
_REF_INTERN_RPC = re.compile(r"^(COB-)?RPC-\d{8}-\d{5}$", re.IGNORECASE)


def _es_referencia_interna_rpc_o_cob(val: str) -> bool:
    s = (val or "").strip()
    return bool(s and _REF_INTERN_RPC.match(s))


def _referencia_interna_desde_numero_documento_pago(nd: str) -> Optional[str]:
    """Si ``pagos.numero_documento`` enlaza un ``pagos_reportados``, devuelve ``referencia_interna``."""
    s = (nd or "").strip()
    if not s:
        return None
    if s.upper().startswith("COB-"):
        s = s[4:].strip()
    if _es_referencia_interna_rpc_o_cob(s):
        return s
    return None


def _enriquecer_documento_columna_pagos_realizados(db: Session, filas: List[dict]) -> None:
    """
    Texto para columna «Documento» en PDF/API: número de operación / voucher del cliente.

    Evita mostrar solo la referencia interna automática (RPC-…) cuando existe
    ``pagos_reportados.numero_operacion`` para el mismo reporte.
    """
    refs: set[str] = set()
    for r in filas:
        nd = (r.get("numero_documento") or "").strip()
        ri = _referencia_interna_desde_numero_documento_pago(nd)
        if ri:
            refs.add(ri)
    by_ri: dict[str, PagoReportado] = {}
    if refs:
        prs = db.execute(
            select(PagoReportado).where(PagoReportado.referencia_interna.in_(sorted(refs)))
        ).scalars().all()
        for obj in prs:
            ri = (getattr(obj, "referencia_interna", None) or "").strip()
            if ri:
                by_ri[ri] = obj
    for r in filas:
        nd = (r.get("numero_documento") or "").strip()
        refp = (r.get("referencia_pago") or "").strip()
        tab = (r.get("referencia_tabla") or "").strip()
        ri = _referencia_interna_desde_numero_documento_pago(nd)
        op_rep = ""
        if ri and ri in by_ri:
            op_rep = (getattr(by_ri[ri], "numero_operacion", None) or "").strip()
        r["numero_operacion_reportado"] = op_rep or None
        if op_rep:
            r["documento_columna"] = op_rep[:100]
            continue
        for cand in (nd, refp):
            if cand and not _es_referencia_interna_rpc_o_cob(cand):
                r["documento_columna"] = cand[:100]
                break
        else:
            r["documento_columna"] = (nd or refp or tab)[:100] if (nd or refp or tab) else None


def listar_pagos_realizados_estado_cuenta(db: Session, prestamo_ids: List[int]) -> List[dict]:
    """
    Pagos operativos del préstamo en tabla ``pagos`` (misma elegibilidad que cascada/cartera).

    Incluye asientos Conciliar ABONOS aunque queden PENDIENTE sin filas en cuota_pagos
    (p. ej. exceso sobre cupo de cuotas tras comprobantes OCR). Antes solo entraba estado=PAGADO
    y el asiento ABONOS-NOTIF-* desaparecía del PDF frente a «Pagos registrados en cartera».

    Excluye pagos cuya cédula no coincide con la del préstamo (asignación errónea a otro crédito).

    Orden: ``fecha_pago`` ascendente (más antiguo primero), luego ``id`` — misma regla que la cascada.
  """
    if not prestamo_ids:
        return []
    ids = sorted({int(x) for x in prestamo_ids if x is not None})
    if not ids:
        return []
    from app.services.pagos_sql_where import _where_pago_elegible_reaplicacion_cascada
    from app.utils.cedula_almacenamiento import normalizar_cedula_almacenamiento

    cedula_por_prestamo: Dict[int, str] = {}
    for pr in db.execute(select(Prestamo).where(Prestamo.id.in_(ids))).scalars().all():
        pid = int(getattr(pr, "id", 0) or 0)
        if pid <= 0:
            continue
        cedula_por_prestamo[pid] = (
            normalizar_cedula_almacenamiento(getattr(pr, "cedula", None) or "") or ""
        ).upper().replace("-", "")

    rows = db.execute(
        select(Pago)
        .where(
            Pago.prestamo_id.in_(ids),
            Pago.monto_pagado > 0,
            _where_pago_elegible_reaplicacion_cascada(),
        )
        .order_by(Pago.fecha_pago.asc().nullslast(), Pago.id.asc())
    ).scalars().all()
    resultado: List[dict] = []
    for raw in rows:
        pg = raw[0] if hasattr(raw, "__getitem__") else raw
        pago_id = int(getattr(pg, "id", 0) or 0)
        prestamo_id = getattr(pg, "prestamo_id", None)
        if prestamo_id is not None:
            ced_prestamo = cedula_por_prestamo.get(int(prestamo_id), "")
            ced_pago = (
                normalizar_cedula_almacenamiento(getattr(pg, "cedula_cliente", None) or "")
                or ""
            ).upper().replace("-", "")
            if ced_prestamo and ced_pago and ced_prestamo != ced_pago:
                logger.warning(
                    "estado_cuenta: omitiendo pago_id=%s prestamo_id=%s "
                    "(cedula pago %s != cedula prestamo %s)",
                    pago_id,
                    prestamo_id,
                    ced_pago,
                    ced_prestamo,
                )
                continue
        banco = (getattr(pg, "institucion_bancaria", None) or "").strip() or "no disponible"
        fp = getattr(pg, "fecha_pago", None)
        fr = getattr(pg, "fecha_registro", None)
        moneda_raw = (getattr(pg, "moneda_registro", None) or "").strip().upper()
        es_bs = moneda_raw in ("BS", "BOLIVAR", "BOLIVARES")
        monto_usd = float(getattr(pg, "monto_pagado", 0) or 0)
        monto_bs_val = getattr(pg, "monto_bs_original", None)
        monto_bs_f = float(monto_bs_val) if monto_bs_val is not None else None
        tasa_val = getattr(pg, "tasa_cambio_bs_usd", None)
        tasa_f = float(tasa_val) if tasa_val is not None else None
        if es_bs:
            if monto_bs_f is not None:
                monto_display = f"{monto_bs_f:,.2f} Bs"
            else:
                monto_display = "Bs (monto no disponible en BD)"
            tasa_display = f"{tasa_f:,.6f}" if tasa_f is not None else "-"
        else:
            monto_display = f"{monto_usd:,.2f} USD"
            tasa_display = "-"
        rec = _prestamo_cuota_recibo_desde_pago(db, pago_id)
        if rec:
            rp, rc = rec
        else:
            rp = int(prestamo_id) if prestamo_id is not None else None
            rc = None
        doc = (getattr(pg, "numero_documento", None) or "").strip()
        refp = (getattr(pg, "referencia_pago", None) or "").strip()
        referencia_tabla = (doc or refp or f"Pago #{pago_id}")[:32]
        cedula_comprobante = (getattr(pg, "cedula_cliente", None) or "").strip() or "-"
        aplicacion_cuotas = desglose_aplicacion_cuotas_por_pago(db, pago_id)
        lc = (getattr(pg, "link_comprobante", None) or "").strip()
        doc_ruta = (getattr(pg, "documento_ruta", None) or "").strip()
        raw_link = lc or doc_ruta
        link_foto = (
            comprobante_url_para_enlace_publico(raw_link) if raw_link else None
        )
        resultado.append(
            {
                "pago_id": pago_id,
                "prestamo_id": int(prestamo_id) if prestamo_id is not None else None,
                "banco": banco,
                "fecha_pago_orden": fp.isoformat() if fp is not None else "",
                "fecha_pago_display": _fmt_fecha_hora_pago_estado_cuenta(fp),
                "fecha_registro_display": _fmt_fecha_hora_pago_estado_cuenta(fr),
                "monto_display": monto_display,
                "tasa_display": tasa_display,
                "subtotal_usd": monto_usd,
                "es_bs": es_bs,
                "recibo_prestamo_id": rp,
                "recibo_cuota_id": rc,
                "referencia_tabla": referencia_tabla,
                "numero_documento": doc or None,
                "referencia_pago": refp or None,
                "cedula_comprobante": cedula_comprobante,
                "aplicacion_cuotas": aplicacion_cuotas,
                "link_comprobante": (link_foto or None),
            }
        )
    _enriquecer_documento_columna_pagos_realizados(db, resultado)
    pend = [r for r in resultado if not _link_comprobante_es_url_http(r.get("link_comprobante"))]
    if pend:
        pseudo = [
            {
                "numero_documento": (r.get("numero_documento") or ""),
                "link_comprobante": None,
                "documento_ruta": None,
            }
            for r in pend
        ]
        enriquecer_items_link_comprobante_desde_gmail(db, pseudo)
        for r, p in zip(pend, pseudo):
            u = (p.get("link_comprobante") or "").strip()
            if u:
                r["link_comprobante"] = comprobante_url_para_enlace_publico(u)
    # 1 = pago más antiguo (misma lógica que cascada / revisión manual).
    for num, r in enumerate(resultado, start=1):
        r["numero_pago"] = num
    return resultado



def _cargar_prestamo_para_estado_cuenta(db, prestamo_id: int):
    """
    Carga el prestamo para armar el PDF. Si en BD no existe la columna fecha_liquidado (migracion 023),
    evita db.get(Prestamo) porque el mapper haria SELECT de esa columna y PostgreSQL fallaria.
    """
    from types import SimpleNamespace

    from sqlalchemy import select

    from app.models.prestamo import Prestamo

    from app.services.prestamo_db_compat import prestamos_tiene_columna_fecha_liquidado

    if prestamos_tiene_columna_fecha_liquidado(db):
        return db.get(Prestamo, prestamo_id)
    t = Prestamo.__table__
    cols = tuple(c for c in t.c if c.name != "fecha_liquidado")
    rowm = db.execute(select(*cols).where(t.c.id == prestamo_id)).mappings().first()
    if not rowm:
        return None
    return SimpleNamespace(**dict(rowm))


def obtener_datos_estado_cuenta_prestamo(db, prestamo_id: int, sincronizar: bool = True):

    """

    Obtiene datos formateados para PDF/JSON de estado de cuenta de UN prestamo.

    Consumidores: GET /prestamos/{id}/estado-cuenta, GET /prestamos/{id}/estado-cuenta/pdf,
    obtener_datos_estado_cuenta_cliente.

    Tabla de amortizacion completa si el prestamo esta en ESTADOS_PRESTAMO_TABLA_AMORTIZACION.

    Si sincronizar es False, el llamador debe haber llamado ya sincronizar_pagos_pendientes_a_prestamos.

    """

    from sqlalchemy import select

    from app.models.cliente import Cliente

    from app.models.cuota import Cuota

    from app.services.cuota_estado import estado_cuota_para_mostrar, hoy_negocio

    from app.services.pagos_cuotas_sincronizacion import sincronizar_pagos_pendientes_a_prestamos



    prestamo = _cargar_prestamo_para_estado_cuenta(db, prestamo_id)

    if not prestamo:

        return None

    if estado_prestamo_es_desistimiento(getattr(prestamo, "estado", None)):
        return None



    cliente = db.get(Cliente, prestamo.cliente_id)

    if not cliente:

        return None



    cedula_display = (getattr(cliente, "cedula", None) or "").strip()

    nombre = (getattr(cliente, "nombres", None) or "").strip()

    email = (getattr(cliente, "email", None) or "").strip()

    email_sec = (getattr(cliente, "email_secundario", None) or "").strip()

    correos_cliente = emails_destino_desde_objeto(cliente)



    if sincronizar:

        try:

            sincronizar_pagos_pendientes_a_prestamos(db, [prestamo_id])

        except Exception as sync_exc:

            logger.warning(

                "obtener_datos_estado_cuenta_prestamo: sincronizar_pagos_pendientes_a_prestamos prestamo_id=%s: %s",

                prestamo_id,

                sync_exc,

            )



    prestamos_list = [{

        "id": prestamo.id,

        "producto": getattr(prestamo, "producto", None) or "",

        "total_financiamiento": float(getattr(prestamo, "total_financiamiento", 0) or 0),

        "estado": getattr(prestamo, "estado", None) or "",

    }]



    cuotas_pendientes = []

    total_pendiente = 0.0

    fecha_corte_dt = hoy_negocio()



    cuotas_rows = db.execute(

        select(Cuota)

        .where(Cuota.prestamo_id == prestamo_id)

        .order_by(Cuota.numero_cuota)

    ).scalars().all()



    for cuota in cuotas_rows:

        monto_cuota = float(getattr(cuota, "monto", 0) or 0)

        total_pagado = float(getattr(cuota, "total_pagado", 0) or 0)

        monto_pendiente = max(0.0, monto_cuota - total_pagado)



        if monto_pendiente <= 0:

            continue



        total_pendiente += monto_pendiente

        fv = getattr(cuota, "fecha_vencimiento", None)

        fv_date = fv.date() if fv and hasattr(fv, "date") else fv

        estado_mostrar = estado_cuota_para_mostrar(total_pagado, monto_cuota, fv_date, fecha_corte_dt)



        cuotas_pendientes.append({

            "prestamo_id": prestamo_id,

            "numero_cuota": getattr(cuota, "numero_cuota", ""),

            "fecha_vencimiento": fv.isoformat() if fv else "",

            "monto": monto_pendiente,

            "estado": estado_mostrar,

            "estado_etiqueta": etiqueta_estado_cuota(estado_mostrar),

        })



    amortizaciones_por_prestamo = []

    estado = (getattr(prestamo, "estado", "") or "").strip().upper()



    if prestamo_muestra_tabla_amortizacion(estado):

        cuotas_amortizacion = db.execute(

            select(Cuota)

            .where(Cuota.prestamo_id == prestamo_id)

            .order_by(Cuota.numero_cuota)

        ).scalars().all()



        if cuotas_amortizacion:

            cuotas_data = []

            for c in cuotas_amortizacion:

                total_pagado_c = float(getattr(c, "total_pagado", 0) or 0)

                monto_c = float(getattr(c, "monto", 0) or 0)

                fv_c = getattr(c, "fecha_vencimiento", None)

                fv_date_c = fv_c.date() if fv_c and hasattr(fv_c, "date") else fv_c

                estado_cuota = estado_cuota_para_mostrar(total_pagado_c, monto_c, fv_date_c, fecha_corte_dt)

                # USD aplicado a esta cuota (reparto desde pagos de cobranza; ver sección Pagos realizados).
                pago_conc_display = f"{total_pagado_c:,.2f}" if total_pagado_c > 0 else "-"

                cuotas_data.append({

                    "id": c.id,

                    "numero_cuota": getattr(c, "numero_cuota", ""),

                    "fecha_vencimiento": fv_c.strftime("%d/%m/%Y") if fv_c else "",

                    "monto_capital": float(getattr(c, "monto_capital", 0) or 0),

                    "monto_interes": float(getattr(c, "monto_interes", 0) or 0),

                    "monto_cuota": monto_c,

                    "saldo_capital_final": float(getattr(c, "saldo_capital_final", 0) or 0),

                    "pago_conciliado_display": pago_conc_display,

                    "total_pagado_cuota": total_pagado_c,

                    "estado": estado_cuota,

                    "estado_etiqueta": etiqueta_estado_cuota(estado_cuota),

                })



            amortizaciones_por_prestamo.append({

                "prestamo_id": prestamo_id,

                "producto": getattr(prestamo, "producto", None) or "Prestamo",

                "cuotas": cuotas_data,

            })



    return {

        "cedula_display": cedula_display,

        "nombre": nombre,

        "correo_1": email,

        "correo_2": email_sec or None,

        "email": email,

        "email_secundario": email_sec or None,

        "emails": correos_cliente,

        "prestamos_list": prestamos_list,

        "cuotas_pendientes": cuotas_pendientes,

        "total_pendiente": total_pendiente,

        "fecha_corte": fecha_corte_dt,

        "amortizaciones_por_prestamo": amortizaciones_por_prestamo,
        "pagos_realizados": listar_pagos_realizados_estado_cuenta(db, [prestamo_id]),

    }

def obtener_datos_estado_cuenta_cliente(
    db,
    cedula_lookup: str,
    *,
    solo_aprobados_o_liquidados: bool = False,
    excluir_prestamos_liquidados_y_desistimiento: bool = False,
):
    """
    Arma el mismo dict que consume generar_pdf_estado_cuenta para todos los prestamos
    del cliente (cedula normalizada sin guiones). Reutiliza obtener_datos_estado_cuenta_prestamo
    por cada prestamo para que cuotas pendientes, totales y amortizacion coincidan con
    GET /prestamos/{id}/estado-cuenta, GET /prestamos/{id}/estado-cuenta/pdf y notificaciones liquidado.

    solo_aprobados_o_liquidados: portal público; solo APROBADO / LIQUIDADO.
    En cualquier caso se excluye DESISTIMIENTO (y variantes).
    excluir_prestamos_liquidados_y_desistimiento: Recibos por correo; omitir préstamos
    LIQUIDADO/DESISTIMIENTO del PDF (el envío se corta aparte si no hay cartera activa).
    """
    from sqlalchemy import func, select

    from app.models.cliente import Cliente
    from app.models.prestamo import Prestamo
    from app.services.cuota_estado import hoy_negocio
    from app.services.pagos_cuotas_sincronizacion import sincronizar_pagos_pendientes_a_prestamos

    cedula_lookup = (cedula_lookup or "").strip()
    if not cedula_lookup:
        return None

    cliente_row = db.execute(
        select(Cliente).where(
            expr_cedula_normalizada_para_comparar(Cliente.cedula) == cedula_lookup
        )
    ).scalars().first()

    if not cliente_row:
        return None

    cliente = cliente_row[0] if hasattr(cliente_row, "__getitem__") else cliente_row
    cliente_id = getattr(cliente, "id", None)
    if not cliente_id:
        return None

    nombre = (getattr(cliente, "nombres", None) or "").strip()
    email = (getattr(cliente, "email", None) or "").strip()
    email_sec = (getattr(cliente, "email_secundario", None) or "").strip()
    correos_cliente = emails_destino_desde_objeto(cliente)
    cedula_display = (getattr(cliente, "cedula", None) or "").strip()

    prestamos_rows = db.execute(
        select(Prestamo).where(Prestamo.cliente_id == cliente_id)
    ).scalars().all()

    prestamo_ids = []
    for row in prestamos_rows:
        p = row[0] if hasattr(row, "__getitem__") else row
        est = getattr(p, "estado", None)
        # Nunca DESISTIMIENTO (ni variantes).
        if estado_prestamo_es_desistimiento(est):
            continue
        if excluir_prestamos_liquidados_y_desistimiento and estado_prestamo_es_liquidado(
            est
        ):
            continue
        if solo_aprobados_o_liquidados and not estado_prestamo_permite_estado_cuenta(
            est
        ):
            continue
        prestamo_ids.append(p.id)

    if prestamo_ids:
        try:
            sincronizar_pagos_pendientes_a_prestamos(db, prestamo_ids)
        except Exception as sync_exc:
            logger.warning(
                "obtener_datos_estado_cuenta_cliente: sincronizar_pagos_pendientes_a_prestamos "
                "cliente_id=%s: %s",
                cliente_id,
                sync_exc,
            )

    merged = {
        "cedula_display": cedula_display,
        "nombre": nombre,
        "correo_1": email,
        "correo_2": email_sec or None,
        "email": email,
        "email_secundario": email_sec or None,
        "emails": correos_cliente,
        "prestamos_list": [],
        "cuotas_pendientes": [],
        "total_pendiente": 0.0,
        "fecha_corte": hoy_negocio(),
        "amortizaciones_por_prestamo": [],
        "pagos_realizados": [],
    }

    for pid in prestamo_ids:
        part = obtener_datos_estado_cuenta_prestamo(db, pid, sincronizar=False)
        if not part:
            continue
        merged["fecha_corte"] = part["fecha_corte"]
        merged["prestamos_list"].extend(part["prestamos_list"])
        merged["cuotas_pendientes"].extend(part["cuotas_pendientes"])
        merged["total_pendiente"] += float(part["total_pendiente"] or 0)
        merged["amortizaciones_por_prestamo"].extend(part["amortizaciones_por_prestamo"])

    merged["pagos_realizados"] = listar_pagos_realizados_estado_cuenta(db, prestamo_ids)

    return merged


def serializar_estado_cuenta_payload_json(datos: Optional[Dict[str, Any]]) -> Optional[Dict[str, Any]]:
    """Convierte el dict de obtener_datos_estado_cuenta_* a JSON (fecha_corte como ISO)."""
    if not datos:
        return None
    payload = copy.deepcopy(datos)
    fc = payload.get("fecha_corte")
    if hasattr(fc, "isoformat"):
        payload["fecha_corte"] = fc.isoformat()
    for pr in payload.get("pagos_realizados") or []:
        if isinstance(pr, dict):
            pr.pop("fecha_pago_orden", None)
    return payload
